#include <cassert>
#include <cmath>
#include <iostream>
#include "waypoint_apply.h"
int main(){ proposal_min::WaypointGeo points[2]={{35.0,139.0},{35.0001,139.0001}}; for(auto state:{proposal_min::WaypointSafetyState::Boot,proposal_min::WaypointSafetyState::ArmedIdle,proposal_min::WaypointSafetyState::Running,proposal_min::WaypointSafetyState::EStop,proposal_min::WaypointSafetyState::Fault}){proposal_min::WaypointStore store{};store.revision=4;store.count=1;store.points[0]=points[0]; proposal_min::WaypointRequest request{9,5,1,2,0.5f,points}; auto r=proposal_min::applyWaypointSet(state,request,store); assert(r.status==proposal_min::WaypointApplyStatus::Rejected&&store.revision==4&&store.count==1&&store.points[0].latitudeDeg==35.0); } proposal_min::WaypointStore store{}; proposal_min::WaypointRequest good{9,1,1,2,0.5f,points}; auto accepted=proposal_min::applyWaypointSet(proposal_min::WaypointSafetyState::Disarmed,good,store); assert(accepted.status==proposal_min::WaypointApplyStatus::Accepted&&store.revision==1&&store.count==2); auto duplicate=proposal_min::applyWaypointSet(proposal_min::WaypointSafetyState::Disarmed,good,store); assert(duplicate.status==proposal_min::WaypointApplyStatus::Duplicate&&store.revision==1); proposal_min::WaypointGeo bad[1]={{NAN,139.0}}; proposal_min::WaypointRequest invalid{10,2,1,1,0.5f,bad}; auto rejected=proposal_min::applyWaypointSet(proposal_min::WaypointSafetyState::Disarmed,invalid,store); assert(rejected.status==proposal_min::WaypointApplyStatus::Rejected&&store.revision==1&&store.count==2); std::cout<<"WAYPOINT_APPLY_HOST_PASS states=6 rejected_non_disarmed=5 accepted_disarmed=1 duplicate=1 invalid_nan=1 atomicity=ok\n"; }